import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
try:
    import fastchacha
    _enc = fastchacha.encrypt
except Exception:
    _enc = None
from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]; nonce = problem["nonce"]
        pt = problem["plaintext"]; aad = problem["associated_data"] or b""
        if _enc is not None and len(key) == 32 and len(nonce) == 12:
            ct, tag = _enc(key, nonce, pt, aad)
            return {"ciphertext": ct, "tag": tag}
        out = ChaCha20Poly1305(key).encrypt(nonce, pt, aad)
        return {"ciphertext": out[:-16], "tag": out[-16:]}

