        if(nt){ for(int k=0;k<8;k++) _mm_stream_si128((__m128i*)(out+16*k),b[k]); }
        else { for(int k=0;k<8;k++) _mm_storeu_si128((__m128i*)(out+16*k),b[k]); }
        __m128i lo=_mm_setzero_si128(),mid=lo,hi=lo;
        clmul_acc(_mm_xor_si128(X,_mm_shuffle_epi8(b[0],bs)),Hp[7],&lo,&mid,&hi);
        for(int k=1;k<8;k++) clmul_acc(_mm_shuffle_epi8(b[k],bs),Hp[7-k],&lo,&mid,&hi);
        X=reduce(lo,mid,hi);
