    for(int loop=0;loop<2;loop++){
        k=0; prvnumfree=numfree; numfree=0;
        while(k<prvnumfree){
            i=freerow[k++]; const double*c=cost+(size_t)i*n;
            umin=c[0]-v[0]; j1=0; usubmin=DBL_MAX;
            for(j=1;j<n;j++){ h=c[j]-v[j];
                if(h<usubmin){ if(h>=umin){usubmin=h;j2=j;} else {usubmin=umin;umin=h;j2=j1;j1=j;} } }
            i0=y[j1];
            if(umin<usubmin) v[j1]=v[j1]-(usubmin-umin);
            else if(i0>=0){ j1=j2; i0=y[j2]; }
            x[i]=j1; y[j1]=i;
            if(i0>=0){ if(umin<usubmin) freerow[--k]=i0; else freerow[numfree++]=i0; }
        }
    }
    /* augmentation */
    for(f=0;f<numfree;f++){
        int freerowi=freerow[f]; const double*c=cost+(size_t)freerowi*n;
        for(j=0;j<n;j++){ d[j]=c[j]-v[j]; pred[j]=freerowi; collist[j]=j; }
        low=0; up=0; int unassigned_found=0;
        while(!unassigned_found){
            if(up==low){
                last=low-1;
                min=d[collist[up++]];
                for(k=up;k<n;k++){ j=collist[k]; h=d[j];
                    if(h<=min){ if(h<min){up=low;min=h;} collist[k]=collist[up]; collist[up++]=j; } }
                for(k=low;k<up;k++) if(y[collist[k]]<0){endofpath=collist[k];unassigned_found=1;break;}
            }
            if(!unassigned_found){
                j1=collist[low++]; i=y[j1]; const double*ci=cost+(size_t)i*n;
                h=ci[j1]-v[j1]-min;
                for(k=up;k<n;k++){ j=collist[k]; v2=ci[j]-v[j]-h;
                    if(v2<d[j]){ pred[j]=i;
