                            else { collist[k]=collist[up]; collist[up++]=j; } }
                        d[j]=v2; } }
            }
        }
        for(k=0;k<=last;k++){ j1=collist[k]; v[j1]+=d[j1]-min; }
        do{ i=pred[endofpath]; y[endofpath]=i; j1=endofpath; endofpath=x[i]; x[i]=j1; }while(i!=freerowi);
    }
    free(y);free(freerow);free(collist);free(matches);free(pred);free(v);free(d);
