   x out. returns 0 ok, -1 no full matching. */
typedef struct { double d; int j; } HE;
static void hpush(HE*h,int*sz,double d,int j){int k=(*sz)++;while(k>0){int p=(k-1)>>1;if(h[p].d<=d)break;h[k]=h[p];k=p;}h[k].d=d;h[k].j=j;}
static HE hpop(HE*h,int*sz){HE top=h[0];HE last=h[--(*sz)];int k=0,n=*sz;for(;;){int c=2*k+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[k]=h[c];k=c;}h[k]=last;return top;}
int sspl(int n,const int*rp,const int*ci,const double*cv,double*v,int*x,int nnz){
    int *y=malloc(n*sizeof(int)),*pred=malloc(n*sizeof(int)),*done=calloc(n,sizeof(int)),*touched=malloc(n*sizeof(int)),*fin=malloc(n*sizeof(int));
    double *d=malloc(n*sizeof(double)); HE*h=malloc((nnz+n+8)*sizeof(HE));
    int *xc=malloc(n*sizeof(int)); double *xcost=malloc(n*sizeof(double));
    int ret=0;
    for(int j=0;j<n;j++){y[j]=-1;d[j]=DBL_MAX;}
    for(int i=0;i<n;i++)x[i]=-1;
    for(int r=0;r<n;r++){
        int nt=0,nf=0,sz=0,end=-1; double dend=0;
        for(int e=rp[r];e<rp[r+1];e++){int j=ci[e];double dd=cv[e]-v[j];
            if(d[j]==DBL_MAX)touched[nt++]=j; if(dd<d[j]){d[j]=dd;pred[j]=r;hpush(h,&sz,dd,j);}}
        while(sz>0){HE t=hpop(h,&sz);int j=t.j;if(done[j]||t.d>d[j])continue;
            if(y[j]<0){end=j;dend=t.d;break;}
            done[j]=1;fin[nf++]=j;int i=y[j];double ui=xcost[i]-v[j];
            for(int e=rp[i];e<rp[i+1];e++){int k=ci[e];if(done[k])continue;double nd=t.d+cv[e]-v[k]-ui;
                if(d[k]==DBL_MAX)touched[nt++]=k; if(nd<d[k]){d[k]=nd;pred[k]=i;hpush(h,&sz,nd,k);}}
        }
        if(end<0){ret=-1;break;}
        for(int q=0;q<nf;q++){int j=fin[q];v[j]+=d[j]-dend;}
        /* augment */
        int j=end;
        for(;;){int i=pred[j];int pj=x[i];
            /* find cost of edge i->j */
            double c=0;for(int e=rp[i];e<rp[i+1];e++)if(ci[e]==j){c=cv[e];break;}
            y[j]=i;x[i]=j;xcost[i]=c; if(i==r)break; j=pj;}
        for(int q=0;q<nt;q++){d[touched[q]]=DBL_MAX;done[touched[q]]=0;}
    }
    free(y);free(pred);free(done);free(touched);free(fin);free(d);free(h);free(xc);free(xcost);
    return ret;
}
/* count violations: c_ij - v_j < u_i - tol; u_i=c_{i,x_i}-v_{x_i}. writes flagged (i,j) up to cap */
int check(int n,const double*M,const double*v,const int*x,double tol,int*out,int cap){
    int cnt=0;
    for(int i=0;i<n;i++){const double*c=M+(size_t)i*n;double ui=c[x[i]]-v[x[i]]-tol;
        for(int j=0;j<n;j++) if(c[j]-v[j]<ui){ if(cnt<cap){out[2*cnt]=i;out[2*cnt+1]=j;} cnt++; } }
    return cnt;
}
