static int expand_key(const uint8_t*key,int klen,uint8_t*w){
  int Nk=klen/4, Nr=Nk+6, total=4*(Nr+1);
  memcpy(w,key,klen);
  uint8_t rcon=1;
  for(int i=Nk;i<total;i++){
    uint8_t t[4]; memcpy(t,w+4*(i-1),4);
    if(i%Nk==0){
      uint8_t x=t[0]; t[0]=sbox[t[1]]^rcon; t[1]=sbox[t[2]]; t[2]=sbox[t[3]]; t[3]=sbox[x];
      rcon=(uint8_t)((rcon<<1)^((rcon&0x80)?0x1b:0));
    } else if(Nk>6 && i%Nk==4){
      for(int j=0;j<4;j++) t[j]=sbox[t[j]];
    }
    for(int j=0;j<4;j++) w[4*i+j]=w[4*(i-Nk)+j]^t[j];
  }
  return Nr;
}

typedef struct { __m128i rk[15]; int Nr; __m128i H[8]; } ctx_t;

static inline __m128i aes_enc(const ctx_t*c,__m128i x){
  x=_mm_xor_si128(x,c->rk[0]);
  for(int r=1;r<c->Nr;r++) x=_mm_aesenc_si128(x,c->rk[r]);
  return _mm_aesenclast_si128(x,c->rk[c->Nr]);
}

static inline void clmul_acc(__m128i a,__m128i b,__m128i*lo,__m128i*mid,__m128i*hi){
  *lo=_mm_xor_si128(*lo,_mm_clmulepi64_si128(a,b,0x00));
  *hi=_mm_xor_si128(*hi,_mm_clmulepi64_si128(a,b,0x11));
  *mid=_mm_xor_si128(*mid,_mm_xor_si128(_mm_clmulepi64_si128(a,b,0x10),_mm_clmulepi64_si128(a,b,0x01)));
}
static inline __m128i reduce(__m128i tmp3,__m128i mid,__m128i tmp6){
