  tmp7=_mm_srli_epi32(tmp3,31); tmp8=_mm_srli_epi32(tmp6,31);
  tmp3=_mm_slli_epi32(tmp3,1); tmp6=_mm_slli_epi32(tmp6,1);
  tmp9=_mm_srli_si128(tmp7,12); tmp8=_mm_slli_si128(tmp8,4); tmp7=_mm_slli_si128(tmp7,4);
  tmp3=_mm_or_si128(tmp3,tmp7); tmp6=_mm_or_si128(tmp6,tmp8); tmp6=_mm_or_si128(tmp6,tmp9);
  tmp7=_mm_slli_epi32(tmp3,31); tmp8=_mm_slli_epi32(tmp3,30); tmp9=_mm_slli_epi32(tmp3,25);
  tmp7=_mm_xor_si128(tmp7,tmp8); tmp7=_mm_xor_si128(tmp7,tmp9);
