    double wnorm=nrm2(n,w);
    int m=j+1;
    for(int c=0;c<m;c++){const double*vc=&Vm(0,c);double s=0;for(int i=0;i<n;i++)s+=vc[i]*w[i];h[c]=s;}
    for(int i=0;i<n;i++) resid[i]=w[i];
    for(int c=0;c<m;c++){const double*vc=&Vm(0,c);double hc=h[c];for(int i=0;i<n;i++)resid[i]-=vc[i]*hc;}
    if(j>0) Hm(j,j-1)=betaj;
    double rn=nrm2(n,resid);
    if(!(rn>0.717*wnorm)){
      int it=0;
      double xt[256];
      for(;;){
        for(int c=0;c<m;c++){const double*vc=&Vm(0,c);double s=0;for(int i=0;i<n;i++)s+=vc[i]*resid[i];xt[c]=s;}
        for(int c=0;c<m;c++){const double*vc=&Vm(0,c);double hc=xt[c];for(int i=0;i<n;i++)resid[i]-=vc[i]*hc;}
        for(int c=0;c<m;c++) h[c]+=xt[c];
        double r1=nrm2(n,resid);
        if(r1>0.717*rn){rn=r1;break;}
        rn=r1; it++;
        if(it<=1) continue;
        for(int i=0;i<n;i++)resid[i]=0; rn=0; break;
      }
    }
    for(int c=0;c<m;c++) Hm(c,j)=h[c];
    *rnorm=rn;
  }
  int kp=k+np; double work[256];
  for(int i=(k>1?k:1)-1;i<kp-1;i++){
    double tst1=fabs(Hm(i,i))+fabs(Hm(i+1,i+1));
    if(tst1==0.0){char c='1';tst1=dlanhs_(&c,&kp,H,&ldh,work);}
    double th=ULP*tst1; if(th<SMLNUM)th=SMLNUM;
    if(fabs(Hm(i+1,i))<=th) Hm(i+1,i)=0.0;
  }
  return 0;
}

static void dneigh(double rnorm,int n,double*H,int ldh,double*rr,double*ri,double*bd,double*Q,int ldq,double*wk){
  double*T=wk; /* n*n */
  for(int j=0;j<n;j++)for(int i=0;i<n;i++)T[i+j*n]=Hm(i,j);
  for(int j=0;j<n;j++)bd[j]=0; bd[n-1]=1.0;
  int t=1,f=0,one=1,info=0;
  dlahqr_(&t,&f,&n,&one,&n,T,&n,rr,ri,&one,&one,bd,&one,&info);
  char side='R',how='A'; int sel[256]; double vl[1]; int m;
  dtrevc_(&side,&how,sel,&n,T,&n,vl,&n,Q,&ldq,&n,&m,wk+n*n,&info);
  int iconj=0;
  for(int i=0;i<n;i++){
    if(fabs(ri[i])<=0){double tt=nrm2(n,&Qm(0,i));for(int r=0;r<n;r++)Qm(r,i)*=1.0/tt;}
    else if(iconj==0){double tt=dlapy2(nrm2(n,&Qm(0,i)),nrm2(n,&Qm(0,i+1)));
      for(int r=0;r<n;r++){Qm(r,i)*=1.0/tt;Qm(r,i+1)*=1.0/tt;} iconj=1;}
    else iconj=0;
  }
  double*w=wk+n*n;
  for(int i=0;i<n;i++){double s=0;for(int r=0;r<n;r++)s+=Qm(r,i)*bd[r];w[i]=s;}
  iconj=0;
  for(int i=0;i<n;i++){
    if(fabs(ri[i])<=0) bd[i]=rnorm*fabs(w[i]);
    else if(iconj==0){bd[i]=rnorm*dlapy2(w[i],w[i+1]);bd[i+1]=bd[i];iconj=1;}
    else iconj=0;
  }
}

static void napps(int n,int*kevp,int np,double*sr,double*si,double*V,double*H,int ldh,double*resid,double*Q,int ldq,double*work,double*wd){
  int kev=*kevp; int kplusp=kev+np;
  for(int j=0;j<kplusp;j++)for(int i=0;i<kplusp;i++)Qm(i,j)=(i==j);
  if(np==0) return;
  int cconj=0; char c1='1';
  for(int jj=0;jj<np;jj++){
    double sigmar=sr[jj],sigmai=si[jj];
    if(cconj){cconj=0;continue;}
    else if(jj<np-1 && fabs(sigmai)>0) cconj=1;
    else if(jj==np-1 && fabs(sigmai)>0){kev++;continue;}
    int istart=0;
    for(;;){
      int iend=kplusp-1;
      for(int i=istart;i<kplusp-1;i++){
        double tst1=fabs(Hm(i,i))+fabs(Hm(i+1,i+1));
        if(tst1==0.0){int nn=kplusp-jj;tst1=dlanhs_(&c1,&nn,H,&ldh,work);}
        double th=ULP*tst1; if(th<SMLNUM)th=SMLNUM;
        if(fabs(Hm(i+1,i))<=th){iend=i;Hm(i+1,i)=0.0;break;}
      }
      if(!(istart==iend || (istart+1==iend && fabs(sigmai)>0))){
        double h11=Hm(istart,istart),h21=Hm(istart+1,istart);
        if(fabs(sigmai)<=0){
          double f=h11-sigmar,g=h21;
          for(int i=istart;i<iend;i++){
            double c,s,r; dlartg_(&f,&g,&c,&s,&r);
            if(i>istart){Hm(i,i-1)=r;Hm(i+1,i-1)=0.0;}
            for(int j=i;j<kplusp;j++){double t=c*Hm(i,j)+s*Hm(i+1,j);Hm(i+1,j)=-s*Hm(i,j)+c*Hm(i+1,j);Hm(i,j)=t;}
            int lim=(i+2<iend?i+2:iend);
            for(int j=0;j<=lim;j++){double t=c*Hm(j,i)+s*Hm(j,i+1);Hm(j,i+1)=-s*Hm(j,i)+c*Hm(j,i+1);Hm(j,i)=t;}
            lim=(i+jj+1<kplusp-1?i+jj+1:kplusp-1);
            for(int j=0;j<=lim;j++){double t=c*Qm(j,i)+s*Qm(j,i+1);Qm(j,i+1)=-s*Qm(j,i)+c*Qm(j,i+1);Qm(j,i)=t;}
            if(i<iend-1){f=Hm(i+1,i);g=Hm(i+2,i);}
          }
        } else {
          double h12=Hm(istart,istart+1),h22=Hm(istart+1,istart+1),h32=Hm(istart+2,istart+1);
          double s=2.0*sigmar,t=dlapy2(sigmar,sigmai);
          double u[3]; u[0]=(h11*(h11-s)+t*t)/h21+h12; u[1]=h11+h22-s; u[2]=h32;
          for(int i=istart;i<iend;i++){
            int nr=iend-i+1; if(nr>3)nr=3; int inc=1; double tau;
            dlarfg_(&nr,&u[0],&u[1],&inc,&tau);
            if(i>istart){Hm(i,i-1)=u[0];Hm(i+1,i-1)=0.0;if(i<iend-1)Hm(i+2,i-1)=0.0;}
            u[0]=1.0;
            char L='L',R='R'; int nc=kplusp-i; 
            dlarf_(&L,&nr,&nc,u,&inc,&tau,&Hm(i,i),&ldh,work);
            int ir=(i+3<iend?i+3:iend)+1;
            dlarf_(&R,&ir,&nr,u,&inc,&tau,&Hm(0,i),&ldh,work);
            dlarf_(&R,&kplusp,&nr,u,&inc,&tau,&Qm(0,i),&ldq,work);
            if(i<iend-1){u[0]=Hm(i+1,i);u[1]=Hm(i+2,i);if(i<iend-2)u[2]=Hm(i+3,i);}
          }
        }
      }
      istart=iend+1;
      if(iend>=kplusp-1)break;
    }
  }
  for(int i=0;i<kev;i++){
    if(Hm(i+1,i)<0.0){
      for(int j=i;j<kplusp;j++)Hm(i+1,j)=-Hm(i+1,j);
      int lim=(i+3<kplusp?i+3:kplusp); for(int j=0;j<lim;j++)Hm(j,i+1)=-Hm(j,i+1);
      lim=(i+np+2<kplusp?i+np+2:kplusp); for(int j=0;j<lim;j++)Qm(j,i+1)=-Qm(j,i+1);
    }
  }
  for(int i=0;i<kev;i++){
    double tst1=fabs(Hm(i,i))+fabs(Hm(i+1,i+1));
    if(tst1==0.0){tst1=dlanhs_(&c1,&kev,H,&ldh,work);}
    double th=ULP*tst1; if(th<SMLNUM)th=SMLNUM;
    if(Hm(i+1,i)<=th)Hm(i+1,i)=0.0;
  }
  double hk=Hm(kev,kev-1);
  double*w1=wd,*w2=wd+n;
  if(hk>0){for(int r=0;r<n;r++)w2[r]=0;for(int c=0;c<kplusp;c++){double q=Qm(c,kev);const double*vc=&Vm(0,c);for(int r=0;r<n;r++)w2[r]+=vc[r]*q;}}
  for(int i=0;i<kev;i++){
    int m=kplusp-i; int qc=kev-1-i;
    for(int r=0;r<n;r++)w1[r]=0;
    for(int c=0;c<m;c++){double q=Qm(c,qc);const double*vc=&Vm(0,c);for(int r=0;r<n;r++)w1[r]+=vc[r]*q;}
    memcpy(&Vm(0,kplusp-1-i),w1,sizeof(double)*n);
  }
  memmove(&Vm(0,0),&Vm(0,kplusp-kev),sizeof(double)*n*kev);
  if(hk>0) memcpy(&Vm(0,kev),w2,sizeof(double)*n);
  double qs=Qm(kplusp-1,kev-1);
  for(int r=0;r<n;r++)resid[r]*=qs;
  if(hk>0) for(int r=0;r<n;r++)resid[r]+=hk*Vm(r,kev);
  *kevp=kev;
}

int ira(int n,const int*ip,const int*ix,const double*d,int nev0,int ncv,int maxiter,
        double*V,double*H,double*resid,double*copies,int*out,double*rn_out){
  Mat A={n,ip,ix,d};
  ULP=DBL_EPSILON; SMLNUM=DBL_MIN*((double)n/ULP);
  double eps=DBL_EPSILON*0.5, tol=eps, eps23=pow(eps,2.0/3.0);
  int ldh=ncv,ldq=ncv,kplusp=ncv;
  double*w=malloc(sizeof(double)*(3*n+10*ncv*ncv+20*ncv+100));
  double*wd=w+n; double*h=wd+2*n; double*rr=h+ncv+2; double*ri=rr+ncv; double*bd=ri+ncv;
  double*Q=bd+ncv; double*wk=Q+ncv*ncv; double*work=wk+4*ncv*ncv+4*ncv;
  memset(H,0,sizeof(double)*ncv*ncv);
  /* getv0: resid = A*v0 */
  matvec(&A,resid,w); memcpy(resid,w,sizeof(double)*n);
  double rnorm=nrm2(n,resid);
  int nev=nev0,np=ncv-nev0,iter=0,nconv=0,status=0;
  if(naitr(&A,n,0,nev,V,H,ldh,resid,&rnorm,w,h)){status=-9;goto done;}
  for(;;){
    iter++;
    if(naitr(&A,n,nev,np,V,H,ldh,resid,&rnorm,w,h)){status=-9;goto done;}
    dneigh(rnorm,kplusp,H,ldh,rr,ri,bd,Q,ldq,wk);
    memcpy(copies,rr,sizeof(double)*kplusp);memcpy(copies+ncv,ri,sizeof(double)*kplusp);memcpy(copies+2*ncv,bd,sizeof(double)*kplusp);
    nev=nev0;np=ncv-nev0;int numcnv=nev;
    dngets(&nev,&np,rr,ri,bd);
    if(nev==nev0+1)numcnv=nev0+1;
    nconv=0;
    for(int i=0;i<numcnv;i++){double t=dlapy2(rr[np+i],ri[np+i]);if(t<eps23)t=eps23;if(bd[np+i]<=tol*t)nconv++;}
    int npt=np; for(int j=0;j<npt;j++) if(bd[j]==0.0){np--;nev++;}
    if(nconv>=numcnv||iter>maxiter||np==0){ if(iter>maxiter && nconv<numcnv) status=1; break;}
    int nevbef=nev;
    nev+= (nconv<np/2?nconv:np/2);
    if(nev==1&&kplusp>=6)nev=kplusp/2; else if(nev==1&&kplusp>3)nev=2;
    if(nev>kplusp-2)nev=kplusp-2;
    np=kplusp-nev;
    if(nevbef<nev) dngets(&nev,&np,rr,ri,bd);
    napps(n,&nev,np,rr,ri,V,H,ldh,resid,Q,ldq,work,wd);
    rnorm=nrm2(n,resid);
  }
done:
  out[0]=nconv; out[1]=iter; *rn_out=rnorm;
  free(w);
  return status;
}
