#include <stdlib.h>
#include <string.h>
#include <math.h>
int lapjv(int n, const double *c, int *x);

/* binary heap on columns keyed by d */
typedef struct { int *h; int *pos; int sz; double *d; } Heap;
static void hup(Heap *H,int p){ int *h=H->h; double *d=H->d; int e=h[p]; double de=d[e];
  while(p>0){int q=(p-1)>>1; if(d[h[q]]<=de) break; h[p]=h[q]; H->pos[h[p]]=p; p=q;} h[p]=e; H->pos[e]=p; }
static void hdown(Heap *H,int p){ int *h=H->h; double *d=H->d; int e=h[p]; double de=d[e]; int sz=H->sz;
  while(1){int l=2*p+1; if(l>=sz) break; int r=l+1; int m=(r<sz && d[h[r]]<d[h[l]])?r:l; if(d[h[m]]>=de) break; h[p]=h[m]; H->pos[h[p]]=p; p=m;} h[p]=e; H->pos[e]=p; }
static void hpush(Heap *H,int e){ H->h[H->sz]=e; H->pos[e]=H->sz; H->sz++; hup(H,H->sz-1); }
static int hpop(Heap *H){ int r=H->h[0]; H->sz--; if(H->sz>0){ H->h[0]=H->h[H->sz]; H->pos[H->h[0]]=0; hdown(H,0);} H->pos[r]=-1; return r; }

/* returns 0 ok (optimal verified), 1 fell back to dense */
int solve(int n, const double *c, int *x, int K) {
    if(K>n) K=n;
    /* build candidate edges: K smallest per row, K smallest per column */
    int *cnt = calloc(n,sizeof(int));
    int *rk = malloc((size_t)n*K*sizeof(int));
    double *bv = malloc(K*sizeof(double)); int *bi = malloc(K*sizeof(int));
    for(int i=0;i<n;i++){ const double *ci=c+(size_t)i*n; int m=0;
        for(int j=0;j<n;j++){ double t=ci[j];
            if(m<K){ int p=m++; while(p>0&&bv[p-1]>t){bv[p]=bv[p-1];bi[p]=bi[p-1];p--;} bv[p]=t;bi[p]=j; }
            else if(t<bv[K-1]){ int p=K-1; while(p>0&&bv[p-1]>t){bv[p]=bv[p-1];bi[p]=bi[p-1];p--;} bv[p]=t;bi[p]=j; } }
        for(int k=0;k<K;k++) rk[(size_t)i*K+k]=bi[k];
    }
    /* column K smallest: process via columns */
    int *ck = malloc((size_t)n*K*sizeof(int));
    {
      double *BV=malloc((size_t)n*K*sizeof(double)); int *BI=malloc((size_t)n*K*sizeof(int)); int *M=calloc(n,sizeof(int));
      for(int i=0;i<n;i++){ const double *ci=c+(size_t)i*n;
        for(int j=0;j<n;j++){ double t=ci[j]; double *bvj=BV+(size_t)j*K; int *bij=BI+(size_t)j*K; int m=M[j];
          if(m<K){ int p=m; M[j]=m+1; while(p>0&&bvj[p-1]>t){bvj[p]=bvj[p-1];bij[p]=bij[p-1];p--;} bvj[p]=t;bij[p]=i; }
          else if(t<bvj[K-1]){ int p=K-1; while(p>0&&bvj[p-1]>t){bvj[p]=bvj[p-1];bij[p]=bij[p-1];p--;} bvj[p]=t;bij[p]=i; } } }
      memcpy(ck,BI,(size_t)n*K*sizeof(int)); free(BV);free(BI);free(M);
    }
    /* CSR: row i edges = rk[i] U {j : i in ck[j]} (duplicates ok) */
    for(int i=0;i<n;i++) cnt[i]=K;
    for(int j=0;j<n;j++) for(int k=0;k<K;k++) cnt[ck[(size_t)j*K+k]]++;
    int *ptr=malloc((n+1)*sizeof(int)); ptr[0]=0; for(int i=0;i<n;i++) ptr[i+1]=ptr[i]+cnt[i];
    int *col=malloc(ptr[n]*sizeof(int)); double *cv=malloc(ptr[n]*sizeof(double));
    int *fill=malloc(n*sizeof(int));
    for(int i=0;i<n;i++){ fill[i]=ptr[i]; for(int k=0;k<K;k++){ int j=rk[(size_t)i*K+k]; col[fill[i]]=j; cv[fill[i]++]=c[(size_t)i*n+j]; } }
    for(int j=0;j<n;j++) for(int k=0;k<K;k++){ int i=ck[(size_t)j*K+k]; col[fill[i]]=j; cv[fill[i]++]=c[(size_t)i*n+j]; }
