    for(int j=0;j<n;j++){ y[j]=-1; d[j]=INFINITY; hpos[j]=-1; }
    Heap H={hh,hpos,0,d};
    int fail=0;
    /* init v = column min over candidate edges? keep 0 */
    for(int f=0; f<n && !fail; f++){
        int ntch=0, nsc=0; int i=f; double base=0; int end=-1; double mn=0;
