            for(int e=ptr[r];e<ptr[r+1];e++){ int j=col[e]; if(hpos[j]==-2) continue;
                double t=off+cv[e]-v[j];
                if(t<d[j]){ if(d[j]==INFINITY){touched[ntch++]=j; d[j]=t; pred[j]=r; hpush(&H,j);} else { d[j]=t; pred[j]=r; hup(&H,hpos[j]); } } }
            if(H.sz==0){ fail=1; break; }
            int j=hpop(&H); hpos[j]=-2; 
            if(y[j]<0){ end=j; mn=d[j]; break; }
            scanned[nsc++]=j; cur_col=j; r=y[j];
        }
        if(fail) break;
        for(int k=0;k<nsc;k++){ int j=scanned[k]; v[j]+=d[j]-mn; }
        for(int k=0;k<ntch;k++){ int j=touched[k]; d[j]=INFINITY; hpos[j]=-1; }
        H.sz=0;
        int j=end; while(1){ int ii=pred[j]; y[j]=ii; int t=x[ii]; x[ii]=j; if(ii==f) break; j=t; }
        (void)base;(void)dr;
    }
    if(!fail){
        /* verify dual feasibility on full matrix */
        for(int i=0;i<n && !fail;i++){ const double *ci=c+(size_t)i*n; double u=ci[x[i]]-v[x[i]];
            double mnr=INFINITY; for(int j=0;j<n;j++){ double t=ci[j]-v[j]; mnr = t<mnr?t:mnr; }
            if(mnr < u - 1e-12) fail=1; }
    }
    free(v);free(d);free(y);free(pred);free(done);free(touched);free(hh);free(hpos);free(ptr);free(col);free(cv);
    if(fail){ lapjv(n,c,x); return 1; }
    return 0;
}
