typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
static naupd_t fn = 0;
int arinit(const char* path){
    void* h = dlopen(path, RTLD_NOW|RTLD_LOCAL);
    if(!h) return -1;
