}
/* state layout: 6 doubles, then ints; ido at byte 0x34 */
int arloop(void* st, double* resid, double* v, int n, int* ipntr, double* workd, double* workl,
           const int* indptr, const int* indices, const double* data){
    int* ido = (int*)((char*)st + 0x34);
    for(;;){
