/* y_j = sum_i A[i,j]*x[i] candidates. L lanes, V = vector width 4 */
double cand(int m,const double*a,const double*x,int L,int fma,int red,int tail){
  double s[64]={0}; int i=0;
  for(;i+L<=m;i+=L) for(int k=0;k<L;k++) s[k]=fma?__builtin_fma(a[i+k],x[i+k],s[k]):s[k]+a[i+k]*x[i+k];
  if(tail==1){ /* vector tail per 4 lanes */
    for(;i+4<=m;i+=4) for(int k=0;k<4;k++) s[k]=fma?__builtin_fma(a[i+k],x[i+k],s[k]):s[k]+a[i+k]*x[i+k];
  }
  double t;
  int nv=L/4;
  if(red==0){t=0;for(int k=0;k<L;k++)t+=s[k];}
  else if(red==1){int w=L;while(w>1){w/=2;for(int k=0;k<w;k++)s[k]+=s[k+w];}t=s[0];}
  else { /* vectors summed sequentially then horizontal */
    double v[4];for(int k=0;k<4;k++)v[k]=s[k];
    for(int q=1;q<nv;q++)for(int k=0;k<4;k++)v[k]+=s[4*q+k];
    if(red==2) t=(v[0]+v[2])+(v[1]+v[3]);
    else if(red==3) t=(v[0]+v[1])+(v[2]+v[3]);
    else if(red==4) t=((v[0]+v[1])+v[2])+v[3];
    else t=(v[0]+v[2])+(v[1]+v[3]);
    if(red==5){ /* tree over vectors */ 
      int w=nv; while(w>1){w/=2;for(int q=0;q<w;q++)for(int k=0;k<4;k++)s[4*q+k]+=s[4*(q+w)+k];}
      t=(s[0]+s[2])+(s[1]+s[3]);
    }
    if(red==6){int w=nv; while(w>1){w/=2;for(int q=0;q<w;q++)for(int k=0;k<4;k++)s[4*q+k]+=s[4*(q+w)+k];}
